import os
from dataclasses import dataclass
from typing import Any, Dict, Optional
from urllib.parse import urljoin

import requests


@dataclass
class FederatedUserProfile:
    subject: str
    email: Optional[str]
    name: Optional[str]
    given_name: Optional[str]
    family_name: Optional[str]
    picture: Optional[str]
    issuer: Optional[str]
    raw: Dict[str, Any]


class IBMAppIDFederationClient:
    def __init__(
        self,
        client_id: Optional[str] = None,
        client_secret: Optional[str] = None,
        issuer: Optional[str] = None,
        region: Optional[str] = None,
        timeout: int = 20,
    ) -> None:
        self.client_id = client_id or os.getenv("IBM_APPID_CLIENT_ID")
        self.client_secret = client_secret or os.getenv("IBM_APPID_CLIENT_SECRET")
        self.issuer = issuer or os.getenv("IBM_APPID_ISSUER")
        self.region = region or os.getenv("IBM_APPID_REGION")
        self.timeout = timeout

        if not self.client_id or not self.client_secret:
            raise ValueError("IBM_APPID_CLIENT_ID and IBM_APPID_CLIENT_SECRET are required")

        if not self.issuer:
            if self.region:
                self.issuer = f"https://{self.region}.appid.cloud.ibm.com/oauth/v4"
            else:
                raise ValueError("IBM_APPID_ISSUER or IBM_APPID_REGION is required")

        self.session = requests.Session()
        self.session.auth = (self.client_id, self.client_secret)

    def token(self, authorization_code: str, redirect_uri: str) -> Dict[str, Any]:
        token_url = urljoin(self.issuer.rstrip("/") + "/", "token")
        data = {
            "grant_type": "authorization_code",
            "code": authorization_code,
            "redirect_uri": redirect_uri,
        }
        resp = self.session.post(token_url, data=data, timeout=self.timeout)
        resp.raise_for_status()
        return resp.json()

    def userinfo(self, access_token: str) -> Dict[str, Any]:
        userinfo_url = urljoin(self.issuer.rstrip("/") + "/", "userinfo")
        headers = {"Authorization": f"Bearer {access_token}"}
        resp = self.session.get(userinfo_url, headers=headers, timeout=self.timeout)
        resp.raise_for_status()
        return resp.json()

    @staticmethod
    def normalize_claims(claims: Dict[str, Any]) -> FederatedUserProfile:
        subject = claims.get("sub") or claims.get("subject") or ""
        if not subject:
            raise ValueError("Missing subject claim")

        return FederatedUserProfile(
            subject=subject,
            email=claims.get("email"),
            name=claims.get("name"),
            given_name=claims.get("given_name"),
            family_name=claims.get("family_name"),
            picture=claims.get("picture"),
            issuer=claims.get("iss"),
            raw=claims,
        )

    def fetch_and_normalize_user_profile(
        self,
        authorization_code: Optional[str] = None,
        redirect_uri: Optional[str] = None,
        access_token: Optional[str] = None,
    ) -> FederatedUserProfile:
        if access_token is None:
            if not authorization_code or not redirect_uri:
                raise ValueError("Either access_token or both authorization_code and redirect_uri are required")
            token_response = self.token(authorization_code, redirect_uri)
            access_token = token_response.get("access_token")
            if not access_token:
                raise ValueError("No access_token returned by IBM App ID token endpoint")

        claims = self.userinfo(access_token)
        return self.normalize_claims(claims)
